// Client-side downloads for finished slides.
//
// Slide text is generated by the planner but kept OUT of the image itself
// (image models garble lettering). For a "with text" download we draw it onto
// the image here, in the browser, in the same style as the on-screen preview
// in ResultsGrid. This is presentation only: the text comes from the job.

type Downloadable = { url: string; slideText: string | null };

export function slideFilename(type: "image" | "video", index: number): string {
  return type === "video" ? "postwise-clip.mp4" : `postwise-${String(index + 1).padStart(2, "0")}.jpg`;
}

function saveBlob(blob: Blob, filename: string) {
  const objectUrl = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = objectUrl;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(objectUrl);
}

function openInNewTab(url: string) {
  const a = document.createElement("a");
  a.href = url;
  a.target = "_blank";
  a.rel = "noopener noreferrer";
  a.click();
}

/** Splits text into lines that fit `maxWidth` at the context's current font. */
function wrapLines(ctx: CanvasRenderingContext2D, text: string, maxWidth: number): string[] {
  const lines: string[] = [];
  let line = "";
  for (const word of text.split(/\s+/)) {
    const next = line ? `${line} ${word}` : word;
    if (line && ctx.measureText(next).width > maxWidth) {
      lines.push(line);
      line = word;
    } else {
      line = next;
    }
  }
  if (line) lines.push(line);
  return lines;
}

async function renderWithText(image: Blob, text: string): Promise<Blob> {
  const bitmap = await createImageBitmap(image);
  const { width: w, height: h } = bitmap;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("No 2D canvas");
  ctx.drawImage(bitmap, 0, 0);

  // Upper third: clear of TikTok's and Instagram's bottom UI (caption, buttons).
  const fontSize = Math.round(w * 0.058);
  ctx.font = `700 ${fontSize}px Inter, system-ui, sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  const lines = wrapLines(ctx, text, w * 0.8);
  const lineHeight = fontSize * 1.45;
  const padX = fontSize * 0.5;
  let y = h * 0.17 + lineHeight / 2;

  for (const line of lines) {
    const boxW = ctx.measureText(line).width + padX * 2;
    ctx.fillStyle = "rgba(11, 11, 12, 0.78)";
    ctx.beginPath();
    ctx.roundRect(w / 2 - boxW / 2, y - lineHeight / 2, boxW, lineHeight, fontSize * 0.3);
    ctx.fill();
    ctx.fillStyle = "#ffffff";
    ctx.fillText(line, w / 2, y);
    y += lineHeight + fontSize * 0.12;
  }

  return new Promise((resolve, reject) =>
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("toBlob failed"))), "image/jpeg", 0.92)
  );
}

/**
 * Downloads one slide, with its text drawn on when `withText` is set and the
 * slide has text. If the image can't be fetched (CORS, network), it opens in
 * a new tab so the creator can still save it.
 */
export async function downloadSlide(asset: Downloadable, filename: string, withText: boolean): Promise<void> {
  try {
    const res = await fetch(asset.url, { mode: "cors" });
    if (!res.ok) throw new Error(`fetch failed: ${res.status}`);
    const blob = await res.blob();
    if (withText && asset.slideText && blob.type.startsWith("image/")) {
      try {
        saveBlob(await renderWithText(blob, asset.slideText), filename);
        return;
      } catch {
        // Fall through to the plain image rather than failing the download.
      }
    }
    saveBlob(blob, filename);
  } catch {
    openInNewTab(asset.url);
  }
}
